INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (134, 180, 'BOPP BOPET cigarette tear tape envelop tear strip', '../upload/image/20180929/20180929103823_98225.jpg', '<p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPP BOPET cigarette tear tape envelop tear strip</strong></span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP/BOPET self adhesive tear tape lines were for packing/opening of cigarette packs and other packs. it was self adhesive tear tape.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> tear tape have BOPP tear tape, BOPET tear tape,cigarette tear tape,self adhesive tear tape,and other non cigarette usage tear tapes Various sizes for adhesive tear tape:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> a) Thickness of tear tape: 25-40UM b) Width of tear tape rolls: 1.6mm-6.0mm</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> c) Length of tear tape rolls: 5,000m-70,000m</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 2) Printing design: a) Color printing of tear tape rolls: gold, single gold, single silver, full solid red, yellow,white,black, etc. b) Logo printing of tear tape rolls: ink printing logo, laser, holographic effect</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 3.) Packing for of tear tape rolls: Cartons (16rolls/carton)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Certification: ISO9001, ISO14001, OHSMS18000 </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper,envelop tear strip</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Specitications for Self Adhesive Tear Strio Size 1.6 mm. X 16.000 m. </span></p> <p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1. Description</span></p> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Transparent Tear Strip in reel </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Inside diameter of core 29-30 mm. : Outside diameter of core 34-35 </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Length of core 100士2mm.</span><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2. Size</span></p> <p><br/></p> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Shape of core similar to the sample</span> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1.5-1.7 mm. X 16,000 m. per reel</span></p> <p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Tensile Strength</span></p> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Not less than19 N/1.6 mm. </span> <p><br/></p>', '2026-09-06 20:58:45');